command:
// ==========================================
// LUNAS WIRKUNG: SCHLIMMER KATER (APHASMA)
//
// - 1 gültiger Zweibeiner als Ziel (max. 8 Schritt)
// - zentrale Zweibeiner-Erkennung über Block 2
// - alle weiteren / ungültigen Targets = Misserfolg, Gabe geht dennoch durch
// - Dauer: QS Stunden (nach dem nächsten Schlaf)
// - Schmerz: +QS Stufen (system.status.inpain, Modus 2)
// - Erinnerung: Bruchstücke der letzten QS Stunden
// - gespeichertes Ziel | GM-Button | Framework-Effektanlage
// ==========================================
(async function () {
const macroUuid = this?.uuid || game.macros.getName("Schlimmer Kater")?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Finden ||
    !globalThis.DSK?.Target?.Actor || !globalThis.DSK?.Wesen?.IstZweibeiner ||
    !globalThis.DSK?.Geometrie?.Distanz || !globalThis.DSK?.GMAnfrage?.Speichern ||
    !globalThis.DSK?.GMAnfrage?.Finden || !globalThis.DSK?.GMAnfrage?.Lesen ||
    !globalThis.DSK?.GMAnfrage?.Loeschen || !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen || !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (
    !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden ||
    !DSK_FW?.Target?.Actor || !DSK_FW?.Wesen?.IstZweibeiner ||
    !DSK_FW?.Geometrie?.Distanz || !DSK_FW?.GMAnfrage?.Speichern ||
    !DSK_FW?.GMAnfrage?.Finden || !DSK_FW?.GMAnfrage?.Lesen ||
    !DSK_FW?.GMAnfrage?.Loeschen || !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen || !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.03 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Schlimmer Kater", vollerName = "Schlimmer Kater (Aphasma)", ahne = "Aphasma";
const flagKey = "pendingSchlimmerKaterAphasma", endeKey = "aphasmaSchlimmerKater";
const maxReichweite = 8;
const endeText = "Die Nachwirkungen des Katers sind verflogen. Der Verstand ist wieder klar, der Schmerz lässt nach.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const ladeZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const findeEigeneEffekte = (actor, casterUuid) => (actor?.effects || []).filter(effect =>
    (effect.name || effect.label || "") === vollerName &&
    effect.getFlag("dsk", "isSchlimmerKater") === true &&
    effect.getFlag("dsk", "casterUuid") === casterUuid
);

const beschreibungFuer = (casterName, targetName, qs) =>
    `<b>${casterName}</b> verwebt unsichtbare Magie im Geist von <b>${targetName}</b>.` +
    `<br><br>Wenn das Ziel das nächste Mal schläft, erwacht es mit einem grauenhaften Kater:` +
    `<br>• Erleidet <b>${qs} Stufe(n) Schmerz</b> nach dem Aufwachen.` +
    `<br>• Erinnert sich nur nebelhaft an die <b>${qs} Stunde(n)</b> vor dem Schlafengehen.` +
    `<br><br><i><b>Hinweis für die SL:</b> Der Effekt und der Schmerz sind mechanisch bereits auf dem Ziel-Bogen hinterlegt, treten erzählerisch jedoch erst nach dem nächsten Schlafen ein.</i>` +
    `<br><b>Reichweite:</b> ${maxReichweite} Schritt | <b>Zielkategorie:</b> Zweibeiner`;

// +++ 4 - EFFEKT ANWENDEN +++++++++++++++++++++++++++++++++++++

const wendeEffektAn = async ({ casterActor, targetActor, qs }) => {
    if (!casterActor || !targetActor || !DSK_FW.Wesen.IstZweibeiner(targetActor)) return false;

    const alteEffekte = findeEigeneEffekte(targetActor, casterActor.uuid);
    if (alteEffekte.length) await targetActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));

    const zielEffekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName, ahne,
        beschreibung:
            `Erwacht nach dem nächsten Schlaf mit einem grauenhaften Kater.` +
            `<br><br><b>Schmerz:</b> +${qs} Stufe(n)` +
            `<br><b>Erinnerung:</b> Bruchstücke der letzten ${qs} Stunde(n) vor dem Zubettgehen` +
            `<br><b>Wirkungsdauer:</b> ${qs} Stunde(n) (nach dem nächsten Schlaf)`,
        gabeZiel: "", qs,
        skills: ["system.status.inpain"], key: "direkterSystemwert", formel: String(qs),
        ziel: targetActor,
        duration: { hours: qs, startTime: game.time.worldTime },
        showIcon: 1,
        flags: { dsk: {
            isSchlimmerKater: true, casterUuid: casterActor.uuid,
            qs, schmerzStufen: qs,
            wirkungsende: { sfName: endeKey, basisEffektName: vollerName, beschreibungFuerEnde: endeText }
        }}
    });

    if (!zielEffekt) return false;

    const zielEnde = zielEffekt.getFlag("dsk", "wirkungsende");
    const korrekterSystemwert = (zielEffekt.changes || []).some(change =>
        change.key === "system.status.inpain" &&
        Number(change.mode) === 2 &&
        Number(change.value) === qs
    );

    return Boolean(
        zielEffekt.parent?.uuid === targetActor.uuid &&
        zielEffekt.getFlag("dsk", "isSchlimmerKater") === true &&
        zielEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        Number(zielEffekt.getFlag("dsk", "schmerzStufen")) === qs &&
        zielEnde?.sfName === endeKey &&
        zielEnde?.basisEffektName === vollerName &&
        zielEnde?.beschreibungFuerEnde === endeText &&
        !zielEffekt.statuses?.has("inpain") &&
        korrekterSystemwert
    );
};

// +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;

    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
        ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
        return false;
    }

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const { token: targetToken, actor: targetActor } = await ladeZiel(daten.target);
    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const targetName = daten.target?.name || targetToken?.name || targetActor?.name || "Unbekanntes Ziel";
    const misserfolge = foundry.utils.deepClone(daten.misserfolge || []);
    let erfolgreich = false;

    if (targetActor && DSK_FW.Wesen.IstZweibeiner(targetActor)) {
        try {
            erfolgreich = await wendeEffektAn({ casterActor, targetActor, qs });
        } catch (error) {
            console.error("Schlimmer Kater: Effektanlage fehlgeschlagen.", { casterActor, targetActor, daten, error });
        }
    }

    if (!erfolgreich) misserfolge.unshift({ name: targetName });

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId, gabenName: vollerName, ahne,
        beschreibung: daten.beschreibung || beschreibungFuer(casterName, targetName, qs),
        wirkender: casterName,
        ziele: erfolgreich ? [{ name: `${targetName} – Schmerz +${qs}`, rolle: "Heimgesuchtes Ziel" }] : [],
        misserfolge, dauerText: `${qs} Stunde(n) (nach dem nächsten Schlaf)`, erfolgreich
    });

    if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: Schlimmer Kater auf ${targetName} gelegt. Schmerz +${qs}.`);
    else ui.notifications.error("Luna sagt 🌙: Schlimmer Kater konnte nicht angewendet werden!");

    return true;
};

// +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;
            if (await verarbeiteAnfrage(anfrageActor, daten)) await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
        }
        return;
    }
}

// +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);

// +++ 8 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Schlimmer Kater Probe", "Schlimmer Kater"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Die Magie für den schlimmen Kater konnte nicht gewoben werden.",
        wirkender: casterName, ziele: [], misserfolge: [{ name: casterName }],
        dauerText: "Keine Wirkung", gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });
    await raeumeQSAuf(casterActor);
    return;
}

// +++ 9 - ZIEL PRÜFEN +++++++++++++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);
if (!targets.length) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!");
}

let gueltigesZielToken = null;
const misserfolge = [];

for (const tToken of targets) {
    const tActor = tToken?.actor;
    const tName = tToken?.name || tActor?.name || "Unbekanntes Ziel";

    if (gueltigesZielToken) {
        misserfolge.push({ name: tName, grund: "Schlimmer Kater wirkt nur auf ein Ziel" });
        continue;
    }

    if (!tActor || !DSK_FW.Wesen.IstZweibeiner(tActor)) {
        misserfolge.push({ name: tName, grund: "Kein Zweibeiner" });
        continue;
    }

    const distanz = Math.round(DSK_FW.Geometrie.Distanz(casterToken, tToken) * 10) / 10;
    if (distanz > maxReichweite) {
        misserfolge.push({ name: tName, grund: `${Math.ceil(distanz - maxReichweite)} Schritt zu weit` });
        continue;
    }

    gueltigesZielToken = tToken;
}

// +++ 10 - KEIN GÜLTIGES ZIEL ++++++++++++++++++++++++++++++++

if (!gueltigesZielToken) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: `Keines der ausgewählten Ziele ist ein gültiger Zweibeiner innerhalb von ${maxReichweite} Schritt.`,
        wirkender: casterName, ziele: [], misserfolge,
        dauerText: "Keine Wirkung", gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });
    await raeumeQSAuf(casterActor);
    return;
}

const targetToken = gueltigesZielToken, targetActor = targetToken.actor;
const targetName = targetToken.name || targetActor?.name || "Unbekanntes Ziel";
const targetDaten = DSK_FW.Target.Merken(targetToken);

if (!targetDaten) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Das Ziel konnte nicht gespeichert werden!");
}

// +++ 11 - KARTE + GM-BUTTON ++++++++++++++++++++++++++++++++++

const dauerText = `${qs} Stunde(n) (nach dem nächsten Schlaf)`;
const beschreibung = beschreibungFuer(casterName, targetName, qs);

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid, "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
    ziele: [{ name: `${targetName} – Schmerz +${qs}`, rolle: "Heimgesuchtes Ziel" }],
    misserfolge, dauerText, gmLink, gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid, casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    target: targetDaten, misserfolge, qs, beschreibung,
    sceneId: canvas.scene?.id || null, requestedByUserId: game.user.id,
    messageId: nachricht.id, macroUuid, erstellt: Date.now()
};

// +++ 12 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);
ui.notifications.info("Luna sagt 🌙: Schlimmer Kater wurde bei der Spielleitung zur Anwendung beantragt.");

}).call(this);
